#!/usr/bin/env python3
"""Retain original application form rules, with toolkit-only glue in typed adapters."""
import argparse,hashlib,json,subprocess
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true');p.add_argument('--extractor',type=Path,default=HERE/'FormSourceGen/bin/Release/net10.0/FormSourceGen.dll');a=p.parse_args()
forms={f['name']:f for f in json.loads(subprocess.check_output(['dotnet',str(a.extractor),str(ROOT)],text=True))}
def method(n,m):return next(v['code'] for v in forms[n]['methods'] if v['name']==m)
def prop(n,m):return next(v['code'] for v in forms[n]['properties'] if v['name']==m)
def fingerprint(n):return '// Original '+forms[n]['file']+' SHA256 '+hashlib.sha256((ROOT/forms[n]['file']).read_bytes()).hexdigest()+'\n'
out=['''// Generated by X/UI/generate-application-forms.py; do not edit.
// Original PrePoMax Copyright (C) 2016-2026 Matej Borovinšek; root LICENSE.
using CaeResults;using UserControls;using CaeGlobals;using CaeModel;using CaeMesh;using PrePoMax;using PrePoMax.Forms;using PrePoMax.Settings;
using PrePoMax.Commands;using PrePoMax.Python.Journal;using System.Windows.Forms;
namespace PrePoMaxX.UI;
''']
n='FrmSettings'
out+=[fingerprint(n),'''public sealed class SettingsEditSession {
 readonly Controller controller;readonly Func<string> _getRunningAutomationEndpointUrl;
 Dictionary<string,IViewSettings> _viewSettings;
 public SettingsEditSession(Controller controller,Func<string> endpoint){this.controller=controller;_getRunningAutomationEndpointUrl=endpoint;Settings=controller.Settings.ToDictionary();}
 public string[] Pages=>_viewSettings.Keys.ToArray();
 public PropertySheet Page(string name)=>new(_viewSettings[name]);
 public void Reset(string name){if(_viewSettings[name] is IReset reset)reset.Reset();}
 public void Apply(){foreach(var item in Settings.Values)item.CheckValues();var values=new SettingsContainer(Settings);
 string workDirectory=values.GetWorkDirectory();if(workDirectory!=null && workDirectory.ContainsNonEnglishCharacters() && MessageBoxes.ShowWarningQuestionOKCancel(SolverSettings.NonEnglishDirectoryWarning)==DialogResult.Cancel)return;
 controller.Settings=values;controller.Redraw();}
''',prop(n,'Settings'),'}\n']
n='FrmEditCommands'
out+=[fingerprint(n),'''public sealed class CommandEditSession {
 readonly Controller _controller;List<ViewCommand> _viewCommands;List<Command> _preparedCommands;int _preparedActiveCommandCount;
 public CommandEditSession(Controller controller){_controller=controller;Reset();}
 public void Reset(){_preparedCommands=new(_controller.GetCommands());_preparedActiveCommandCount=_controller.GetActiveCommandCount();_viewCommands=_preparedCommands.Select((c,i)=>new ViewCommand(i+1,c)).ToList();}
 public ViewCommand[] Rows=>_viewCommands.ToArray();
 public PropertySheet Properties(int index)=>new(new ViewObjectTypeDescriptor(_viewCommands[index].Command));
 public void Remove(int index)=>_viewCommands.RemoveAt(index);
 public void Clear()=>_viewCommands.Clear();
 public void Move(int index,int offset){int target=index+offset;if(target<0||target>=_viewCommands.Count)return;var row=_viewCommands[index];_viewCommands.RemoveAt(index);_viewCommands.Insert(target,row);}
 public void Open(string file){CommandsCollection.ReadFromFile(file,out var commands);_viewCommands=commands.Select((c,i)=>new ViewCommand(i+1,c)).ToList();}
 public void Save(string file)=>CommandsCollection.WriteToFile(Commands,file);
 public string PythonText {get{PythonJournalReport report;return PythonJournalExporter.GetText(GetPythonScriptCommands(),null,"Edited command history",out report,1,_controller.GetWorkDirectory());}}
 public void ExportPython(string file)=>PythonJournalExporter.Export(GetPythonScriptCommands(),file,"Edited command history",1,_controller.GetWorkDirectory());
 public void Apply(){if(IsHistoryChangedSincePrepare())throw new CaeException("The history was changed while this dialog was open. Press Reset to load the current history before editing it.");_controller.SetCommands(Commands);}
''',prop(n,'Commands')]+[method(n,m) for m in ['IsHistoryChangedSincePrepare','IsShowingPreparedRows','GetPythonScriptCommands','GetNumOfShownUndoneCommands']]+['}\n']
reorganize=method('FrmEditCommands','btnReorganize_Click').replace('private void btnReorganize_Click(object sender, EventArgs e)','public static List<Command> Reorganize(List<Command> commands)').replace('List<Command> commands = Commands;','').replace('SetCommands(commands);','return commands;')
commandtools='// Generated; original FrmEditCommands SHA256 '+hashlib.sha256((ROOT/forms['FrmEditCommands']['file']).read_bytes()).hexdigest()+'\nusing System;using System.Collections.Generic;using System.Linq;using PrePoMax.Commands;\nnamespace PrePoMax {public static class OriginalCommandTools {'+reorganize+'}}\n'
commandtools='\n'.join(line.rstrip() for line in commandtools.splitlines()).rstrip()+'\n'
commandpath=ROOT/'X/Controller/Host/OriginalCommandTools.g.cs'
if a.check:
 if not commandpath.exists() or commandpath.read_text()!=commandtools:raise SystemExit('Original command ordering rules are stale.')
else:commandpath.write_text(commandtools)
out[-1]='public void Reorganize(){_viewCommands=PrePoMax.OriginalCommandTools.Reorganize(Commands).Select((c,i)=>new ViewCommand(i+1,c)).ToList();}\n}\n'
n='FrmFollowerView'
b=next(v['tryBody'] for v in forms[n]['methods'] if v['name']=='btnOK_Click');b=b[:b.index('this.DialogResult')]+ '_controller.ApplyFollowerView(parameters);\n}'
out+=[fingerprint(n),'''public sealed class FollowerEditSession {
 readonly Controller _controller;readonly ViewFollowerViewParameters _viewFollowerViewParameters;
 public FollowerEditSession(Controller c){_controller=c;_viewFollowerViewParameters=new ViewFollowerViewParameters((c.GetCurrentFollowerViewParameters()??new FollowerViewParameters()).DeepClone());}
 public PropertySheet Properties=>new(_viewFollowerViewParameters);
 public void Pick(string name,int id){if(!_controller.DisplayedMesh.Nodes.ContainsKey(id))throw new CaeException("Select a displayed node.");
 if(name.StartsWith("Center"))_viewFollowerViewParameters.CenterNodeId=id;else if(name.StartsWith("Direction1"))_viewFollowerViewParameters.Direction1NodeId=id;else _viewFollowerViewParameters.Direction2NodeId=id;}
 public void Disable()=>_controller.RemoveCurrentFollowerView();
 public void Apply()''',b,'}\n']
n='FrmMain'
# Plotting is a separate FrmMain partial. Select its original methods explicitly.
plot=next(f for f in json.loads(subprocess.check_output(['dotnet',str(a.extractor),str(ROOT)],text=True)) if f['file']=='PrePoMax/Forms/FrmMain.Plotting.cs')
plotcode='\n'.join(next(m['code'] for m in plot['methods'] if m['name']==name) for name in ['AddHistoryOutputToPlot','AddAmplitudeToPlot','GetCurveName','GetColumnNameRows'])
out+=['// Original plotting SHA256 '+hashlib.sha256((ROOT/plot['file']).read_bytes()).hexdigest(),'public sealed partial class PlotSession {',plotcode,'}']
n='FrmQuery'
out+=[fingerprint(n),"""public sealed class QuerySession {
 readonly Controller _controller;string _queryNumberFormat;int _numOfNodesToSelect=1;double[][] _coorNodesToDraw;readonly List<string> lines=[];Action<string> Form_WriteDataToOutput;
 public QuerySession(Controller c){_controller=c;Form_WriteDataToOutput=lines.Add;UpdateQueryNumberFormat();}
 public string Run(string kind,int[] ids){lines.Clear();UpdateQueryNumberFormat();switch(kind){
 case "Node":OneNodePicked(ids[0]);break;case "Element":OneElementPicked(ids[0]);break;case "Edge":OneEdgePicked(ids[0]);break;case "Surface":OneSurfacePicked(ids[0]);break;case "Part":OnePartPicked(ids[0]);break;
 case "Distance":TwoNodesPicked(ids[0],ids[1]);break;case "Angle":ComputeAngle(ids[0],ids[1],ids[2]);break;case "Circle":ComputeCircle(ids[0],ids[1],ids[2]);break;
 case "Assembly":OutputAssemblyData();break;case "Bounding box":HighlightBoundingBox(OutputBoundingBox());break;default:throw new NotSupportedException(kind);}
 return string.Join(Environment.NewLine,lines);}
"""]
for m in forms[n]['methods']:
 if m['name'] in ['OneNodePicked','OneElementPicked','OneEdgePicked','OneSurfacePicked','OnePartPicked','OutputAssemblyData','OutputElementTypeCounts','OutputMassData','OutputBoundingBox','HighlightBoundingBox','GetBoundingBoxCenter','TwoNodesPicked','ComputeAngle','ComputeCircle','FormatQueryValue','UpdateQueryNumberFormat','Highlight']:out.append(m['code'])
out+=['}']
n='FrmSearchContactPairs'
merge=method(n,'tsmiMergeByMasterSlave_Click').replace('private void tsmiMergeByMasterSlave_Click(object sender, EventArgs e)','private void MergeSelected()').replace('BindingSource binding = dgvData.DataSource as BindingSource;','').replace('List<SearchContactPair> contactPairs = binding.DataSource as List<SearchContactPair>;','List<SearchContactPair> contactPairs = pairs;').replace('SetDataGridViewBinding(contactPairs);','pairs=contactPairs;').replace('dgvData.ClearSelection();','').replace('dgvData.CurrentCell = dgvData.Rows[rowId].Cells[0];','')
out+=[fingerprint(n),'public sealed partial class ContactSearchSession {',method(n,'HighlightContactPairs'),merge,'}']
text='\n'.join(line.rstrip() for line in '\n'.join(out).splitlines()).rstrip()+'\n';path=HERE/'Workbench/OriginalApplicationRules.g.cs'
if a.check:
 if not path.exists() or path.read_text()!=text:raise SystemExit('Original application rules are stale.')
else:path.write_text(text)
